# 0004 veri taşımasının yazdığı kesin imza (granted_by boş + bu gerekçe metni). Başka hiçbir tahmin yapılmaz.
MIGRATION_REASON = "Yükseltme: önceki sürümde satış tüm müşterileri görüyordu"
CREATOR_REASON = "Müşteriyi açan kullanıcı"


def classify(apps, schema_editor):
    """Var olan erişimlerin kaynağını yalnız kesin imzalarla sınıflar; hiçbir erişim silinmez/kapatılmaz.
    Toplu taşınan ve kaynağı belirsiz kayıtlar 'inceleme bekliyor' işaretlenir ve aktif kalır."""
    CustomerAccess = apps.get_model("catalog", "CustomerAccess")
    for a in CustomerAccess.objects.all():
        if a.granted_by_id is None and a.reason == MIGRATION_REASON:
            a.source, a.needs_review = "tasima", True
        elif a.reason == CREATOR_REASON and a.granted_by_id == a.user_id:
            a.source, a.needs_review = "yeni_musteri", False
        elif a.granted_by_id is not None:
            a.source, a.needs_review = ("vekalet" if a.valid_until else "yonetici"), False
        else:
            a.source, a.needs_review = "belirsiz", True
        a.save(update_fields=["source", "needs_review"])


